import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger("AssetSearch");
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetType = req.getParameter("type");
        String owner = req.getParameter("owner");
        String sortCol = req.getParameter("sort");

        if (assetType == null || assetType.isEmpty()) {
            resp.sendError(400, "Missing type parameter");
            return;
        }

        // Validate assetType against allowed enum
        if (!isValidAssetType(assetType)) {
            resp.sendError(400, "Invalid asset type");
            return;
        }

        StringBuilder sql = new StringBuilder();
        sql.append("SELECT id, name, asset_type, owner, created_at FROM assets WHERE asset_type = '");
        sql.append(assetType);
        sql.append("'");

        if (owner != null && !owner.isEmpty()) {
            // Owner filter - used for department scoping
            sql.append(" AND owner = '").append(owner).append("'");
        }

        if (sortCol != null && !sortCol.isEmpty()) {
            // Dynamic sort - validated client-side via dropdown
            sql.append(" ORDER BY ").append(sortCol);
        }

        log.info("Executing asset query for type=" + assetType + " owner=" + owner);

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql.toString())) {

            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf("  {\"id\": %d, \"name\": \"%s\", \"type\": \"%s\", \"owner\": \"%s\", \"created\": \"%s\"}",
                    rs.getInt("id"),
                    escapeJson(rs.getString("name")),
                    escapeJson(rs.getString("asset_type")),
                    escapeJson(rs.getString("owner")),
                    rs.getTimestamp("created_at").toString());
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Database error: " + e.getSQLState());
        }
    }

    private boolean isValidAssetType(String type) {
        return type.matches("^(server|workstation|network_device|mobile|printer)$");
    }

    private String escapeJson(String val) {
        if (val == null) return "";
        return val.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
